<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { api, ApiError, type EmployeeStatusCommand, type User } from '../api'
import { useSession } from '../session'
import { captureRequestScope } from '../request-scope'
const props=defineProps<{user:User}>(),emit=defineEmits<{changed:[]}>(),auth=useSession()
const reason=ref(''),busy=ref(false),message=ref(''),pending=ref<EmployeeStatusCommand|null>(null),observed=ref(false)
const key=computed(()=>`ias.employee.status.${auth.identity?.tenant?.id||''}.${auth.identity?.userId||''}.${props.user.id}`)
const allowed=computed(()=>auth.identity?.realm==='TENANT'&&auth.identity.permissions.includes('identity.employee.manage')&&auth.identity.userId!==props.user.id&&props.user.identityType==='EMPLOYEE')
watch(key,()=>{pending.value=null;observed.value=false;message.value='';try{const raw=sessionStorage.getItem(key.value);if(raw){const p=JSON.parse(raw);if(typeof p.operationId==='string'&&typeof p.expectedSecurityVersion==='string'&&typeof p.reason==='string'&&(p.status===0||p.status===1))pending.value=p}}catch{message.value='无法读取原操作，请联系管理员核验。'}},{immediate:true})
function clear(){sessionStorage.removeItem(key.value);pending.value=null;observed.value=false}
async function send(){if(!allowed.value||busy.value||!auth.csrf)return;if(!pending.value){if(Array.from(reason.value).length<5||Array.from(reason.value).length>200||/[\u0000-\u001f\u007f]/.test(reason.value)){message.value='请输入 5～200 个字符的原因。';return}const current=props.user.status===1||props.user.status==='ENABLED';pending.value={operationId:crypto.randomUUID(),expectedSecurityVersion:props.user.securityVersion,status:current?0:1,reason:reason.value};sessionStorage.setItem(key.value,JSON.stringify(pending.value))}else if(!observed.value)return
 const command={...pending.value},scope=captureRequestScope(auth,()=>pending.value?.operationId===command.operationId&&props.user.id===String(commandTarget));const commandTarget=props.user.id;busy.value=true;message.value='';try{const result=await api.employeeStatus(commandTarget,command,auth.csrf.token);if(!scope.current())return;if(result.operationId!==command.operationId||result.userId!==commandTarget)throw Error('回执不匹配');clear();message.value='员工状态已更新，旧会话已失效。';emit('changed')}catch(e){if(!scope.current())return;if(e instanceof ApiError&&e.status>0&&e.status<500){clear();message.value=`操作未完成：${e.code}，请刷新后核验。`}else{observed.value=false;message.value='结果尚未确认，请先查询原操作。'}}finally{if(scope.current()||!pending.value)busy.value=false}}
async function query(){if(!pending.value||busy.value)return;const command={...pending.value},target=props.user.id,scope=captureRequestScope(auth,()=>pending.value?.operationId===command.operationId&&props.user.id===target);busy.value=true;try{const result=await api.employeeStatusOperation(target,command.operationId);if(!scope.current())return;if(result.operationId!==command.operationId||result.userId!==target)throw Error('回执不匹配');clear();message.value='原操作已完成，请查看当前状态。';emit('changed')}catch(e){if(!scope.current())return;if(e instanceof ApiError&&e.status===404&&e.code==='OPERATION_NOT_OBSERVED'){observed.value=true;message.value='尚未观察到原操作，可核对原参数后显式继续。'}else message.value='原操作结果无法确认，请稍后再查。'}finally{if(scope.current()||!pending.value)busy.value=false}}
</script>
<template><section v-if="allowed" class="panel"><h2>员工状态管理</h2><p>停用会使该员工旧会话失效；历史记录会保留。</p><label>变更原因 <input v-model="reason" maxlength="200" :disabled="!!pending || busy"></label><button v-if="!pending" :disabled="busy" @click="send">{{ user.status===1 || user.status==='ENABLED' ? '确认停用员工' : '确认启用员工' }}</button><template v-else><p>原操作：{{ pending.operationId }} · 目标状态：{{ pending.status===1?'启用':'停用' }} · 原因：{{ pending.reason }}</p><button :disabled="busy" @click="query">查询原操作</button><button v-if="observed" :disabled="busy" @click="send">显式按原参数继续</button></template><p v-if="message" role="status">{{ message }}</p></section></template>
